package com.tengine.core.physics

import com.tengine.core.math.Mathf
import com.tengine.core.math.Vector2
import kotlin.math.abs
import kotlin.math.sqrt

/**
 * Contact point generated by narrowphase collision detection.
 */
class ContactPoint2D(
    val position: Vector2,
    val penetration: Float,
    var normalImpulse: Float = 0f,
    var tangentImpulse: Float = 0f
)

/**
 * Contact manifold between [colliderA] and [colliderB].
 * Convention: [normal] ALWAYS points from [colliderA] toward [colliderB].
 */
class ContactManifold2D(
    val colliderA: Collider2D,
    val colliderB: Collider2D,
    val normal: Vector2,
    val penetration: Float,
    val contacts: List<ContactPoint2D>,
    val friction: Float,
    val restitution: Float
)

/**
 * Exact 2D Narrowphase collision detector implementing:
 * - Circle vs Circle
 * - Circle vs Convex Polygon / OBB
 * - Convex Polygon / OBB vs Convex Polygon / OBB via Separating Axis Theorem (SAT) + Sutherland-Hodgman Edge Clipping!
 */
object Narrowphase2D {

    fun collide(a: Collider2D, b: Collider2D): ContactManifold2D? {
        val friction = PhysicsMaterial2D.combineFriction(a.material, b.material)
        val restitution = PhysicsMaterial2D.combineRestitution(a.material, b.material)

        return when {
            a is CircleCollider2D && b is CircleCollider2D ->
                circleVsCircle(a, b, friction, restitution)

            a is CircleCollider2D && (b is BoxCollider2D || b is PolygonCollider2D) ->
                circleVsPolygon(a, b, extractVertices(b), flipNormal = false, friction, restitution)

            (a is BoxCollider2D || a is PolygonCollider2D) && b is CircleCollider2D ->
                circleVsPolygon(b, a, extractVertices(a), flipNormal = true, friction, restitution)

            (a is BoxCollider2D || a is PolygonCollider2D) && (b is BoxCollider2D || b is PolygonCollider2D) ->
                polygonVsPolygon(a, extractVertices(a), b, extractVertices(b), friction, restitution)

            else -> null
        }
    }

    private fun extractVertices(collider: Collider2D): Array<Vector2> = when (collider) {
        is BoxCollider2D -> collider.getWorldVertices()
        is PolygonCollider2D -> collider.getWorldVertices()
        else -> emptyArray()
    }

    private fun circleVsCircle(
        a: CircleCollider2D,
        b: CircleCollider2D,
        friction: Float,
        restitution: Float
    ): ContactManifold2D? {
        a.syncWorldCircle()
        b.syncWorldCircle()
        val dx = b.worldCenter.x - a.worldCenter.x
        val dy = b.worldCenter.y - a.worldCenter.y
        val rSum = a.worldRadius + b.worldRadius
        val distSq = dx * dx + dy * dy
        if (distSq >= rSum * rSum) return null

        val dist = sqrt(distSq)
        val normal: Vector2
        val penetration: Float
        val contactPos: Vector2

        if (dist <= Mathf.EPSILON) {
            normal = Vector2(0f, 1f)
            penetration = rSum
            contactPos = a.worldCenter.copyOf()
        } else {
            normal = Vector2(dx / dist, dy / dist)
            penetration = rSum - dist
            contactPos = Vector2(
                a.worldCenter.x + normal.x * a.worldRadius,
                a.worldCenter.y + normal.y * a.worldRadius
            )
        }
        return ContactManifold2D(
            colliderA = a,
            colliderB = b,
            normal = normal,
            penetration = penetration,
            contacts = listOf(ContactPoint2D(contactPos, penetration)),
            friction = friction,
            restitution = restitution
        )
    }

    private fun circleVsPolygon(
        circle: CircleCollider2D,
        polyCollider: Collider2D,
        verts: Array<Vector2>,
        flipNormal: Boolean,
        friction: Float,
        restitution: Float
    ): ContactManifold2D? {
        if (verts.size < 3) return null
        circle.syncWorldCircle()
        val c = circle.worldCenter
        val r = circle.worldRadius

        // Find polygon edge with maximum signed distance from circle center
        var maxSeparation = Float.NEGATIVE_INFINITY
        var faceIdx = 0
        val faceNormals = Array(verts.size) { i ->
            val v1 = verts[i]
            val v2 = verts[(i + 1) % verts.size]
            // For CCW polygon, outward edge normal is (dy, -dx).normalized
            Vector2(v2.y - v1.y, -(v2.x - v1.x)).normalizeSelf()
        }

        for (i in verts.indices) {
            val n = faceNormals[i]
            val s = n.x * (c.x - verts[i].x) + n.y * (c.y - verts[i].y)
            if (s > r) return null // Separating axis found!
            if (s > maxSeparation) {
                maxSeparation = s
                faceIdx = i
            }
        }

        val v1 = verts[faceIdx]
        val v2 = verts[(faceIdx + 1) % verts.size]

        // Deep center inside polygon
        if (maxSeparation < Mathf.EPSILON) {
            val outN = faceNormals[faceIdx]
            // Circle -> Polygon normal points opposite of polygon's outward face normal
            val normalAtoB = if (!flipNormal) Vector2(-outN.x, -outN.y) else outN.copyOf()
            val penetration = r - maxSeparation
            val contact = Vector2(c.x - outN.x * r, c.y - outN.y * r)
            return ContactManifold2D(
                colliderA = if (!flipNormal) circle else polyCollider,
                colliderB = if (!flipNormal) polyCollider else circle,
                normal = normalAtoB,
                penetration = penetration,
                contacts = listOf(ContactPoint2D(contact, penetration)),
                friction = friction,
                restitution = restitution
            )
        }

        // Voronoi region check on face segment [v1, v2]
        val edge = v2 - v1
        val cToV1 = c - v1
        val cToV2 = c - v2
        val dot1 = cToV1 dot edge
        val dot2 = (-cToV2) dot edge

        val closest: Vector2 = when {
            dot1 <= 0f -> {
                if (c.distanceSquaredTo(v1) >= r * r) return null
                v1.copyOf()
            }
            dot2 <= 0f -> {
                if (c.distanceSquaredTo(v2) >= r * r) return null
                v2.copyOf()
            }
            else -> {
                val n = faceNormals[faceIdx]
                if (maxSeparation >= r) return null
                Vector2(c.x - n.x * maxSeparation, c.y - n.y * maxSeparation)
            }
        }

        val diff = closest - c // Circle -> Polygon
        val distSq = diff.lengthSquared
        if (distSq >= r * r) return null
        val dist = sqrt(distSq)
        val rawNormal = if (dist > Mathf.EPSILON) diff / dist else -faceNormals[faceIdx]
        val finalNormal = if (!flipNormal) rawNormal else -rawNormal
        val penetration = r - dist

        return ContactManifold2D(
            colliderA = if (!flipNormal) circle else polyCollider,
            colliderB = if (!flipNormal) polyCollider else circle,
            normal = finalNormal,
            penetration = penetration,
            contacts = listOf(ContactPoint2D(closest, penetration)),
            friction = friction,
            restitution = restitution
        )
    }

    private data class AxisQuery(val maxSeparation: Float, val bestFaceIndex: Int)

    private fun findAxisLeastPenetration(vertsA: Array<Vector2>, vertsB: Array<Vector2>): AxisQuery {
        var bestDistance = Float.NEGATIVE_INFINITY
        var bestIndex = 0

        for (i in vertsA.indices) {
            val v1 = vertsA[i]
            val v2 = vertsA[(i + 1) % vertsA.size]
            val normal = Vector2(v2.y - v1.y, -(v2.x - v1.x)).normalizeSelf()

            // Support point on B along -normal
            var bestProj = Float.NEGATIVE_INFINITY
            var supportB = vertsB[0]
            for (vb in vertsB) {
                val proj = (-normal.x) * vb.x + (-normal.y) * vb.y
                if (proj > bestProj) {
                    bestProj = proj
                    supportB = vb
                }
            }

            val dist = normal.x * (supportB.x - v1.x) + normal.y * (supportB.y - v1.y)
            if (dist > bestDistance) {
                bestDistance = dist
                bestIndex = i
            }
        }
        return AxisQuery(bestDistance, bestIndex)
    }

    private fun polygonVsPolygon(
        colA: Collider2D,
        vertsA: Array<Vector2>,
        colB: Collider2D,
        vertsB: Array<Vector2>,
        friction: Float,
        restitution: Float
    ): ContactManifold2D? {
        if (vertsA.size < 3 || vertsB.size < 3) return null

        val queryA = findAxisLeastPenetration(vertsA, vertsB)
        if (queryA.maxSeparation >= 0f) return null

        val queryB = findAxisLeastPenetration(vertsB, vertsA)
        if (queryB.maxSeparation >= 0f) return null

        val flip: Boolean
        val refPoly: Array<Vector2>
        val incPoly: Array<Vector2>
        val refFaceIdx: Int

        // Bias slightly toward A to prevent oscillation on symmetric edge contacts
        if (queryA.maxSeparation >= queryB.maxSeparation * 0.95f - 0.001f) {
            refPoly = vertsA
            incPoly = vertsB
            refFaceIdx = queryA.bestFaceIndex
            flip = false
        } else {
            refPoly = vertsB
            incPoly = vertsA
            refFaceIdx = queryB.bestFaceIndex
            flip = true
        }

        val refV1 = refPoly[refFaceIdx].copyOf()
        val refV2 = refPoly[(refFaceIdx + 1) % refPoly.size].copyOf()
        val sidePlaneNormal = (refV2 - refV1).normalized
        val refFaceNormal = Vector2(sidePlaneNormal.y, -sidePlaneNormal.x) // Outward CCW normal

        // Find incident face on incPoly most anti-parallel to refFaceNormal
        var minDot = Float.POSITIVE_INFINITY
        var incFaceIdx = 0
        for (i in incPoly.indices) {
            val iv1 = incPoly[i]
            val iv2 = incPoly[(i + 1) % incPoly.size]
            val incNormal = Vector2(iv2.y - iv1.y, -(iv2.x - iv1.x)).normalizeSelf()
            val d = refFaceNormal dot incNormal
            if (d < minDot) {
                minDot = d
                incFaceIdx = i
            }
        }

        var incidentFace = arrayOf(
            incPoly[incFaceIdx].copyOf(),
            incPoly[(incFaceIdx + 1) % incPoly.size].copyOf()
        )

        // Clip incident segment against the two side planes of reference face
        val negSideOffset = -(sidePlaneNormal dot refV1)
        val posSideOffset = sidePlaneNormal dot refV2

        incidentFace = clipSegmentToLine(-sidePlaneNormal, negSideOffset, incidentFace) ?: return null
        incidentFace = clipSegmentToLine(sidePlaneNormal, posSideOffset, incidentFace) ?: return null

        val refC = refFaceNormal dot refV1
        val contacts = ArrayList<ContactPoint2D>(2)
        var maxPen = 0f

        for (pt in incidentFace) {
            val separation = (refFaceNormal dot pt) - refC
            if (separation <= 0f) {
                val pen = -separation
                if (pen > maxPen) maxPen = pen
                contacts.add(ContactPoint2D(pt, pen))
            }
        }
        if (contacts.isEmpty()) return null

        val normalAtoB = if (flip) -refFaceNormal else refFaceNormal
        return ContactManifold2D(
            colliderA = colA,
            colliderB = colB,
            normal = normalAtoB,
            penetration = maxPen,
            contacts = contacts,
            friction = friction,
            restitution = restitution
        )
    }

    private fun clipSegmentToLine(
        planeNormal: Vector2,
        offset: Float,
        segment: Array<Vector2>
    ): Array<Vector2>? {
        val out = ArrayList<Vector2>(2)
        val d0 = (planeNormal dot segment[0]) - offset
        val d1 = (planeNormal dot segment[1]) - offset

        if (d0 <= 0f) out.add(segment[0])
        if (d1 <= 0f) out.add(segment[1])

        if (d0 * d1 < 0f && abs(d1 - d0) > Mathf.EPSILON) {
            val alpha = d0 / (d0 - d1)
            out.add(Vector2.lerpUnclamped(segment[0], segment[1], alpha))
        }

        return if (out.size < 2) null else arrayOf(out[0], out[1])
    }
}
